use crate::schema::{FieldDef, FieldType, TypeDef, UnionVariant};
use serde_json::Value;
use std::fmt::Write;

const HEADER: &str = "\
# ---------------------------------------------------------
# AUTO-GENERATED by generate-sdk-types — DO NOT EDIT
# Source: contracts/schemas/*.schema.json
# ---------------------------------------------------------
from __future__ import annotations

from typing import Annotated, Literal, Union

from pydantic import BaseModel, Field";

pub fn emit(types: &[TypeDef]) -> String {
    let mut out = String::new();
    out.push_str(HEADER);
    out.push('\n');

    for typedef in types {
        out.push('\n');
        out.push('\n');
        match typedef {
            TypeDef::StringEnum { name, variants } => {
                emit_string_enum(&mut out, name, variants);
            }
            TypeDef::TaggedUnion {
                name,
                discriminator,
                variants,
            } => {
                emit_tagged_union(&mut out, name, discriminator, variants);
            }
            TypeDef::Struct { name, fields } => {
                emit_struct(&mut out, name, fields);
            }
        }
    }

    out.push('\n');
    out
}

fn emit_string_enum(out: &mut String, name: &str, variants: &[String]) {
    if variants.len() <= 3 {
        let joined = variants
            .iter()
            .map(|v| format!("\"{v}\""))
            .collect::<Vec<_>>()
            .join(", ");
        writeln!(out, "{name} = Literal[{joined}]").expect("write");
    } else {
        writeln!(out, "{name} = Literal[").expect("write");
        for v in variants {
            writeln!(out, "    \"{v}\",").expect("write");
        }
        writeln!(out, "]").expect("write");
    }
}

fn emit_tagged_union(out: &mut String, name: &str, discriminator: &str, variants: &[UnionVariant]) {
    // Emit one class per variant
    let mut class_names: Vec<String> = Vec::new();
    for variant in variants {
        let class_name = format!("{}{}", name, to_pascal_case(&variant.tag_value));
        class_names.push(class_name.clone());

        writeln!(out, "class {class_name}(BaseModel):").expect("write");
        writeln!(
            out,
            "    {discriminator}: Literal[\"{}\"] = \"{}\"",
            variant.tag_value, variant.tag_value
        )
        .expect("write");

        if variant.fields.is_empty() {
            // Already has the discriminator field, no need for pass
        } else {
            for field in &variant.fields {
                let py_type = field_type_to_py(&field.ty);
                if field.required {
                    writeln!(out, "    {}: {py_type}", field.name).expect("write");
                } else if field.has_default {
                    let default_str = py_default_value(&field.default_value, &field.ty);
                    let base_type = unwrap_nullable_for_py(&field.ty);
                    writeln!(out, "    {}: {base_type} = {default_str}", field.name)
                        .expect("write");
                } else {
                    writeln!(out, "    {}: {py_type} = None", field.name).expect("write");
                }
            }
        }

        out.push('\n');
        out.push('\n');
    }

    // Emit the union type alias
    let union_members = class_names.join(", ");
    writeln!(
        out,
        "{name} = Annotated[\n    Union[{union_members}],\n    Field(discriminator=\"{discriminator}\"),\n]"
    )
    .expect("write");
}

fn emit_struct(out: &mut String, name: &str, fields: &[FieldDef]) {
    writeln!(out, "class {name}(BaseModel):").expect("write");
    if fields.is_empty() {
        writeln!(out, "    pass").expect("write");
        return;
    }

    // Emit required fields first (no default), then optional fields
    let mut required_fields: Vec<&FieldDef> = Vec::new();
    let mut optional_fields: Vec<&FieldDef> = Vec::new();

    for field in fields {
        if field.required && !field.has_default {
            required_fields.push(field);
        } else {
            optional_fields.push(field);
        }
    }

    for field in &required_fields {
        let py_type = field_type_to_py(&field.ty);
        writeln!(out, "    {}: {py_type}", field.name).expect("write");
    }

    for field in &optional_fields {
        let py_type = field_type_to_py(&field.ty);
        if field.has_default {
            let default_str = py_default_value(&field.default_value, &field.ty);
            // For a non-null default, unwrap the outer Nullable. For a null
            // default, keep the nullable wrapper — `None` IS the value
            // produced when the field is unset on the wire.
            let default_is_null = matches!(&field.default_value, Some(v) if v.is_null());
            let emit_ty = if default_is_null {
                py_type.clone()
            } else {
                unwrap_nullable_for_py(&field.ty)
            };
            writeln!(out, "    {}: {emit_ty} = {default_str}", field.name).expect("write");
        } else {
            // Not required, no default — Optional with None default
            writeln!(out, "    {}: {py_type} = None", field.name).expect("write");
        }
    }
}

fn unwrap_nullable_for_py(ty: &FieldType) -> String {
    match ty {
        FieldType::Nullable(inner) => field_type_to_py(inner),
        other => field_type_to_py(other),
    }
}

fn field_type_to_py(ty: &FieldType) -> String {
    match ty {
        FieldType::String => "str".to_string(),
        FieldType::Bool => "bool".to_string(),
        FieldType::Int => "int".to_string(),
        FieldType::Float => "float".to_string(),
        FieldType::Ref(name) => name.clone(),
        FieldType::Array(inner) => {
            let inner_py = field_type_to_py(inner);
            format!("list[{inner_py}]")
        }
        FieldType::Map(inner) => {
            let inner_py = field_type_to_py(inner);
            format!("dict[str, {inner_py}]")
        }
        FieldType::Nullable(inner) => {
            let inner_py = field_type_to_py(inner);
            format!("{inner_py} | None")
        }
    }
}

fn py_default_value(default: &Option<Value>, ty: &FieldType) -> String {
    match default {
        Some(Value::Bool(b)) => {
            if *b {
                "True".to_string()
            } else {
                "False".to_string()
            }
        }
        Some(Value::Number(n)) => n.to_string(),
        Some(Value::String(s)) => format!("\"{s}\""),
        Some(Value::Array(arr)) => {
            if arr.is_empty() {
                "Field(default_factory=list)".to_string()
            } else {
                // Non-empty default arrays are unusual; use Field
                let items: Vec<String> = arr
                    .iter()
                    .map(|v| match v {
                        Value::String(s) => format!("\"{s}\""),
                        other => other.to_string(),
                    })
                    .collect();
                format!("Field(default_factory=lambda: [{}])", items.join(", "))
            }
        }
        Some(Value::Object(map)) => {
            if map.is_empty() {
                "Field(default_factory=dict)".to_string()
            } else {
                // Non-empty default objects — use field default factory
                // This handles cases like {"vcpus": 2}
                let ref_name = match ty {
                    FieldType::Ref(name) => Some(name.as_str()),
                    FieldType::Nullable(inner) => match inner.as_ref() {
                        FieldType::Ref(name) => Some(name.as_str()),
                        _ => None,
                    },
                    _ => None,
                };
                if let Some(name) = ref_name {
                    // Build kwargs from the map
                    let kwargs: Vec<String> = map
                        .iter()
                        .map(|(k, v)| match v {
                            Value::String(s) => format!("{k}=\"{s}\""),
                            Value::Number(n) => format!("{k}={n}"),
                            Value::Bool(b) => {
                                if *b {
                                    format!("{k}=True")
                                } else {
                                    format!("{k}=False")
                                }
                            }
                            _ => format!("{k}={v}"),
                        })
                        .collect();
                    format!(
                        "Field(default_factory=lambda: {name}({}))",
                        kwargs.join(", ")
                    )
                } else {
                    "Field(default_factory=dict)".to_string()
                }
            }
        }
        Some(Value::Null) | None => "None".to_string(),
    }
}

fn to_pascal_case(s: &str) -> String {
    s.split(['-', '_'])
        .map(|word| {
            let mut chars = word.chars();
            match chars.next() {
                None => String::new(),
                Some(first) => {
                    let mut result = first.to_uppercase().to_string();
                    result.extend(chars);
                    result
                }
            }
        })
        .collect()
}
